import type { TimerSnapshot } from '../shared/types'

/** Tray icon frames generated by scripts/gen-icons.mjs: 0..7 lid lowering, 8 closed. */
export const TRAY_FRAMES = 9
export const TRAY_CLOSED_FRAME = TRAY_FRAMES - 1

/**
 * Which lid frame the tray shows. The lid lowers as the work period runs out and
 * closes for the break; while paused or snoozed the eye is open again.
 */
export function trayFrame(snap: TimerSnapshot, workMs: number): number {
  if (snap.phase === 'break') return TRAY_CLOSED_FRAME
  if (snap.phase !== 'working' || !(workMs > 0)) return 0
  const left = Math.min(workMs, Math.max(0, snap.msUntilBreak ?? workMs))
  const progress = 1 - left / workMs
  return Math.min(TRAY_CLOSED_FRAME - 1, Math.floor(progress * TRAY_CLOSED_FRAME))
}
